  ('lesson-food-restaurant-vocabulary-5', 'lesson-food-restaurant', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-maewoyo"}'::jsonb, 5),
  ('lesson-food-restaurant-expression-6', 'lesson-food-restaurant', 'expression', '메뉴판 좀 주세요.', 'Could I get a menu?', 'menyupan jom juseyo.', null, null, 6),
  ('lesson-food-restaurant-expression-7', 'lesson-food-restaurant', 'expression', '이거 두 개 주세요.', 'Two of these, please.', 'igeo du gae juseyo.', null, null, 7),
  ('lesson-food-restaurant-expression-8', 'lesson-food-restaurant', 'expression', '계산할게요.', 'I''ll pay now.', 'gyesanhalgeyo.', null, null, 8),
  ('lesson-food-restaurant-listening-9', 'lesson-food-restaurant', 'listening', '주문하시겠어요?', 'Would you like to order?', 'jumunhasigesseoyo?', null, null, 9),
  ('lesson-food-restaurant-speaking-10', 'lesson-food-restaurant', 'speaking', '이거 두 개 주세요. 안 맵게 해 주세요.', 'Two of these please. Not spicy, please.', 'igeo du gae juseyo. an maepge hae juseyo.', null, null, 10),
  ('lesson-food-restaurant-summary-11', 'lesson-food-restaurant', 'summary', null, null, null, null, '{"points":["이거 + counter + 주세요 orders anything you can point at.","계산할게요 asks for the bill.","안 맵게 해 주세요 saves your evening."]}'::jsonb, 11),
  ('lesson-food-convenience-introduction-0', 'lesson-food-convenience', 'introduction', null, 'The 편의점 is a Korean institution. You only need four lines to use one perfectly.', null, null, '{"heading":"Convenience Store"}'::jsonb, 0),
  ('lesson-food-convenience-vocabulary-1', 'lesson-food-convenience', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-pyeonuijeom"}'::jsonb, 1),
  ('lesson-food-convenience-vocabulary-2', 'lesson-food-convenience', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-bongtu"}'::jsonb, 2),
  ('lesson-food-convenience-vocabulary-3', 'lesson-food-convenience', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-yeongsujeung"}'::jsonb, 3),
  ('lesson-food-convenience-vocabulary-4', 'lesson-food-convenience', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-kadeu"}'::jsonb, 4),
  ('lesson-food-convenience-expression-5', 'lesson-food-convenience', 'expression', '봉투 주세요.', 'A bag, please.', 'bongtu juseyo.', null, null, 5),
  ('lesson-food-convenience-expression-6', 'lesson-food-convenience', 'expression', '데워 주세요.', 'Please heat it up.', 'dewo juseyo.', null, null, 6),
  ('lesson-food-convenience-expression-7', 'lesson-food-convenience', 'expression', '괜찮아요.', 'No thanks, I''m fine.', 'gwaenchanayo.', null, null, 7),
  ('lesson-food-convenience-listening-8', 'lesson-food-convenience', 'listening', '봉투 필요하세요?', 'Do you need a bag?', 'bongtu piryohaseyo?', null, null, 8),
  ('lesson-food-convenience-speaking-9', 'lesson-food-convenience', 'speaking', '이거 데워 주세요.', 'Please heat this up.', 'igeo dewo juseyo.', null, null, 9),
  ('lesson-food-convenience-summary-10', 'lesson-food-convenience', 'summary', null, null, null, null, '{"points":["데워 주세요 heats your 도시락.","Bags cost money — say 괜찮아요 to decline.","Most stores have a microwave and hot water for free."]}'::jsonb, 10),
  ('lesson-transport-subway-introduction-0', 'lesson-transport-subway', 'introduction', null, 'Seoul’s subway is signposted in English, but asking a person is still faster when you are lost.', null, null, '{"heading":"Taking the Subway"}'::jsonb, 0),
