  ('lesson-transport-subway-vocabulary-3', 'lesson-transport-subway', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-hwanseung"}'::jsonb, 3),
  ('lesson-transport-subway-vocabulary-4', 'lesson-transport-subway', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-chulgu"}'::jsonb, 4),
  ('lesson-transport-subway-vocabulary-5', 'lesson-transport-subway', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-eodiyeyo"}'::jsonb, 5),
  ('lesson-transport-subway-expression-6', 'lesson-transport-subway', 'expression', '강남역 어떻게 가요?', 'How do I get to Gangnam Station?', 'gangnamyeok eotteoke gayo?', null, null, 6),
  ('lesson-transport-subway-expression-7', 'lesson-transport-subway', 'expression', '어디서 환승해요?', 'Where do I transfer?', 'eodiseo hwanseunghaeyo?', null, null, 7),
  ('lesson-transport-subway-expression-8', 'lesson-transport-subway', 'expression', '삼 번 출구에서 만나요.', 'Let''s meet at exit 3.', 'sam beon chulguesseo mannayo.', null, null, 8),
  ('lesson-transport-subway-listening-9', 'lesson-transport-subway', 'listening', '이번 역은 홍대입구역입니다.', 'This stop is Hongdae Ipgu Station.', 'ibeon yeogeun hongdaeipguyeogimnida.', null, null, 9),
  ('lesson-transport-subway-speaking-10', 'lesson-transport-subway', 'speaking', '홍대입구역 어떻게 가요?', 'How do I get to Hongdae Ipgu Station?', 'hongdaeipguyeok eotteoke gayo?', null, null, 10),
  ('lesson-transport-subway-summary-11', 'lesson-transport-subway', 'summary', null, null, null, null, '{"points":["~ 어떻게 가요? asks for directions anywhere.","Exits are numbered — Koreans meet at exit numbers.","환승 is the transfer station."]}'::jsonb, 11),
  ('lesson-transport-taxi-introduction-0', 'lesson-transport-taxi', 'introduction', null, 'Three lines will get you into a taxi, to your destination, and back out again.', null, null, '{"heading":"Taking a Taxi"}'::jsonb, 0),
  ('lesson-transport-taxi-vocabulary-1', 'lesson-transport-taxi', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-taeksi"}'::jsonb, 1),
  ('lesson-transport-taxi-vocabulary-2', 'lesson-transport-taxi', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-yeok"}'::jsonb, 2),
  ('lesson-transport-taxi-vocabulary-3', 'lesson-transport-taxi', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-yeogiyo-stop"}'::jsonb, 3),
  ('lesson-transport-taxi-expression-4', 'lesson-transport-taxi', 'expression', '강남역으로 가 주세요.', 'To Gangnam Station, please.', 'gangnamyeogeuro ga juseyo.', null, null, 4),
  ('lesson-transport-taxi-expression-5', 'lesson-transport-taxi', 'expression', '여기서 세워 주세요.', 'Please stop here.', 'yeogiseo sewo juseyo.', null, null, 5),
  ('lesson-transport-taxi-expression-6', 'lesson-transport-taxi', 'expression', '카드 되나요?', 'Can I pay by card?', 'kadeu doenayo?', null, null, 6),
  ('lesson-transport-taxi-listening-7', 'lesson-transport-taxi', 'listening', '어디로 모실까요?', 'Where shall I take you?', 'eodiro mosilkkayo?', null, null, 7),
  ('lesson-transport-taxi-speaking-8', 'lesson-transport-taxi', 'speaking', '이 주소로 가 주세요.', 'Please go to this address.', 'i jusoro ga juseyo.', null, null, 8),
  ('lesson-transport-taxi-summary-9', 'lesson-transport-taxi', 'summary', null, null, null, null, '{"points":["목적지 + 으로/로 가 주세요 sets the destination.","여기서 세워 주세요 stops the car.","되나요? asks \"is that possible?\" about anything."]}'::jsonb, 9),
  ('lesson-shopping-sizes-introduction-0', 'lesson-shopping-sizes', 'introduction', null, 'Korean shops are hands-on. Ask to try things and to swap sizes without any awkwardness.', null, null, '{"heading":"Sizes & Colors"}'::jsonb, 0),
  ('lesson-shopping-sizes-vocabulary-1', 'lesson-shopping-sizes', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-halin"}'::jsonb, 1),
  ('lesson-shopping-sizes-vocabulary-2', 'lesson-shopping-sizes', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-eolmayeyo"}'::jsonb, 2),
  ('lesson-shopping-sizes-vocabulary-3', 'lesson-shopping-sizes', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-kadeu"}'::jsonb, 3),
  ('lesson-shopping-sizes-expression-4', 'lesson-shopping-sizes', 'expression', '입어 봐도 돼요?', 'Can I try it on?', 'ibeo bwado dwaeyo?', null, null, 4),
  ('lesson-shopping-sizes-expression-5', 'lesson-shopping-sizes', 'expression', '더 큰 사이즈 있어요?', 'Do you have a bigger size?', 'deo keun saijeu isseoyo?', null, null, 5),
  ('lesson-shopping-sizes-expression-6', 'lesson-shopping-sizes', 'expression', '다른 색 있어요?', 'Do you have another colour?', 'dareun saek isseoyo?', null, null, 6),
  ('lesson-shopping-sizes-listening-7', 'lesson-shopping-sizes', 'listening', '이거 새 상품이에요.', 'This one is brand new.', 'igeo sae sangpumieyo.', null, null, 7),
  ('lesson-shopping-sizes-speaking-8', 'lesson-shopping-sizes', 'speaking', '더 큰 사이즈 있어요?', 'Do you have a bigger size?', 'deo keun saijeu isseoyo?', null, null, 8),
  ('lesson-shopping-sizes-summary-9', 'lesson-shopping-sizes', 'summary', null, null, null, null, '{"points":["~ 있어요? asks if a shop has something.","~해도 돼요? asks permission.","더 + adjective = \"more ~\"."]}'::jsonb, 9),
  ('lesson-conversation-smalltalk-introduction-0', 'lesson-conversation-smalltalk', 'introduction', null, 'Korean small talk runs on food, weather and weekends. Three questions keep any conversation alive.', null, null, '{"heading":"Small Talk"}'::jsonb, 0),
  ('lesson-conversation-smalltalk-vocabulary-1', 'lesson-conversation-smalltalk', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-oneul"}'::jsonb, 1),
  ('lesson-conversation-smalltalk-vocabulary-2', 'lesson-conversation-smalltalk', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-bap"}'::jsonb, 2),
  ('lesson-conversation-smalltalk-vocabulary-3', 'lesson-conversation-smalltalk', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-jaemiisseoyo"}'::jsonb, 3),
  ('lesson-conversation-smalltalk-vocabulary-4', 'lesson-conversation-smalltalk', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-bappayo"}'::jsonb, 4),
  ('lesson-conversation-smalltalk-expression-5', 'lesson-conversation-smalltalk', 'expression', '밥 먹었어요?', 'Have you eaten?', 'bap meogeosseoyo?', null, '{"note":"This is a greeting, not a dinner invitation."}'::jsonb, 5),
  ('lesson-conversation-smalltalk-expression-6', 'lesson-conversation-smalltalk', 'expression', '주말에 뭐 했어요?', 'What did you do on the weekend?', 'jumare mwo haesseoyo?', null, null, 6),
  ('lesson-conversation-smalltalk-expression-7', 'lesson-conversation-smalltalk', 'expression', '요즘 어때요?', 'How have you been lately?', 'yojeum eottaeyo?', null, null, 7),
  ('lesson-conversation-smalltalk-listening-8', 'lesson-conversation-smalltalk', 'listening', '요즘 너무 바빠요.', 'I''m so busy lately.', 'yojeum neomu bappayo.', null, null, 8),
  ('lesson-conversation-smalltalk-speaking-9', 'lesson-conversation-smalltalk', 'speaking', '주말에 뭐 했어요?', 'What did you do on the weekend?', 'jumare mwo haesseoyo?', null, null, 9),
  ('lesson-conversation-smalltalk-summary-10', 'lesson-conversation-smalltalk', 'summary', null, null, null, null, '{"points":["밥 먹었어요? means \"how are you\".","뭐 했어요? asks what someone did.","어때요? asks for an opinion about anything."]}'::jsonb, 10),
  ('lesson-living-delivery-introduction-0', 'lesson-living-delivery', 'introduction', null, 'Korean delivery is fast and phone-based. These lines handle the driver, the app and the front desk.', null, null, '{"heading":"Package Delivery"}'::jsonb, 0),
  ('lesson-living-delivery-vocabulary-1', 'lesson-living-delivery', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-baedal"}'::jsonb, 1),
  ('lesson-living-delivery-vocabulary-2', 'lesson-living-delivery', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-pojang"}'::jsonb, 2),
  ('lesson-living-delivery-vocabulary-3', 'lesson-living-delivery', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-gwaenchanayo"}'::jsonb, 3),
  ('lesson-living-delivery-expression-4', 'lesson-living-delivery', 'expression', '문 앞에 놓아 주세요.', 'Please leave it at the door.', 'mun ape noa juseyo.', null, null, 4),
  ('lesson-living-delivery-expression-5', 'lesson-living-delivery', 'expression', '택배 왔어요?', 'Did the package arrive?', 'taekbae wasseoyo?', null, null, 5),
  ('lesson-living-delivery-expression-6', 'lesson-living-delivery', 'expression', '경비실에 맡겨 주세요.', 'Please leave it with the security desk.', 'gyeongbisire matgyeo juseyo.', null, null, 6),
  ('lesson-living-delivery-listening-7', 'lesson-living-delivery', 'listening', '택배입니다. 문 앞에 뒀어요.', 'Delivery. I left it at the door.', 'taekbaeimnida. mun ape dwosseoyo.', null, null, 7),
  ('lesson-living-delivery-speaking-8', 'lesson-living-delivery', 'speaking', '문 앞에 놓아 주세요.', 'Please leave it at the door.', 'mun ape noa juseyo.', null, null, 8),
  ('lesson-living-delivery-summary-9', 'lesson-living-delivery', 'summary', null, null, null, null, '{"points":["문 앞 = in front of the door.","경비실 is the building security office.","~아/어 주세요 politely asks for a favour."]}'::jsonb, 9),
  ('lesson-travel-airport-introduction-0', 'lesson-travel-airport', 'introduction', null, 'From immigration to the airport bus, this is the Korean you need in your first hour in the country.', null, null, '{"heading":"At the Airport"}'::jsonb, 0),
  ('lesson-travel-airport-vocabulary-1', 'lesson-travel-airport', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-beoseu"}'::jsonb, 1),
  ('lesson-travel-airport-vocabulary-2', 'lesson-travel-airport', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-eodiyeyo"}'::jsonb, 2),
  ('lesson-travel-airport-vocabulary-3', 'lesson-travel-airport', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-kadeu"}'::jsonb, 3),
  ('lesson-travel-airport-expression-4', 'lesson-travel-airport', 'expression', '여행으로 왔어요.', 'I''m here for travel.', 'yeohaengeuro wasseoyo.', null, null, 4),
  ('lesson-travel-airport-expression-5', 'lesson-travel-airport', 'expression', '티머니 카드 주세요.', 'A T-money card, please.', 'timeoni kadeu juseyo.', null, null, 5),
  ('lesson-travel-airport-expression-6', 'lesson-travel-airport', 'expression', '공항버스 어디서 타요?', 'Where do I catch the airport bus?', 'gonghangbeoseu eodiseo tayo?', null, null, 6),
  ('lesson-travel-airport-listening-7', 'lesson-travel-airport', 'listening', '방문 목적이 뭐예요?', 'What is the purpose of your visit?', 'bangmun mokjeogi mwoyeyo?', null, null, 7),
  ('lesson-travel-airport-speaking-8', 'lesson-travel-airport', 'speaking', '공항버스 어디서 타요?', 'Where do I catch the airport bus?', 'gonghangbeoseu eodiseo tayo?', null, null, 8),
  ('lesson-travel-airport-summary-9', 'lesson-travel-airport', 'summary', null, null, null, null, '{"points":["~으로 왔어요 states your purpose.","어디서 타요? asks where to board.","T-money works on every bus, subway and most taxis."]}'::jsonb, 9),
  ('lesson-work-greetings-introduction-0', 'lesson-work-greetings', 'introduction', null, 'Korean offices run on a handful of set phrases. Using them correctly signals that you understand the culture.', null, null, '{"heading":"Office Greetings"}'::jsonb, 0),
  ('lesson-work-greetings-vocabulary-1', 'lesson-work-greetings', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-hoesa"}'::jsonb, 1),
  ('lesson-work-greetings-vocabulary-2', 'lesson-work-greetings', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-sugohasyeotseumnida"}'::jsonb, 2),
  ('lesson-work-greetings-vocabulary-3', 'lesson-work-greetings', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-hoeui"}'::jsonb, 3),
  ('lesson-work-greetings-expression-4', 'lesson-work-greetings', 'expression', '안녕하십니까.', 'Good morning (formal).', 'annyeonghasimnikka.', null, null, 4),
  ('lesson-work-greetings-expression-5', 'lesson-work-greetings', 'expression', '수고하셨습니다.', 'Good work today.', 'sugohasyeotseumnida.', null, '{"note":"Say it to peers and juniors, not to your boss."}'::jsonb, 5),
  ('lesson-work-greetings-expression-6', 'lesson-work-greetings', 'expression', '먼저 들어가 보겠습니다.', 'I''ll head out first.', 'meonjeo deureoga bogesseumnida.', null, null, 6),
  ('lesson-work-greetings-listening-7', 'lesson-work-greetings', 'listening', '회의 세 시에 시작합니다.', 'The meeting starts at 3.', 'hoeui se sie sijakhamnida.', null, null, 7),
  ('lesson-work-greetings-speaking-8', 'lesson-work-greetings', 'speaking', '수고하셨습니다. 먼저 들어가 보겠습니다.', 'Good work today. I''ll head out first.', 'sugohasyeotseumnida. meonjeo deureoga bogesseumnida.', null, null, 8),
  ('lesson-work-greetings-summary-9', 'lesson-work-greetings', 'summary', null, null, null, null, '{"points":["~습니다 is the formal business ending.","수고하셨습니다 closes the workday.","Leaving before others needs a polite phrase."]}'::jsonb, 9),
  ('lesson-conversation-opinions-introduction-0', 'lesson-conversation-opinions', 'introduction', null, 'Korean opinions come wrapped in softeners. Saying something flatly can read as blunt, so learn the cushion first.', null, null, '{"heading":"Giving an Opinion"}'::jsonb, 0),
  ('lesson-conversation-opinions-vocabulary-1', 'lesson-conversation-opinions', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-saenggak"}'::jsonb, 1),
  ('lesson-conversation-opinions-vocabulary-2', 'lesson-conversation-opinions', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-machayo"}'::jsonb, 2),
  ('lesson-conversation-opinions-vocabulary-3', 'lesson-conversation-opinions', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-geulsseyo"}'::jsonb, 3),
  ('lesson-conversation-opinions-expression-4', 'lesson-conversation-opinions', 'expression', '제 생각에는 좋은 것 같아요.', 'In my opinion, it seems good.', 'je saenggageneun joeun geot gatayo.', null, '{"note":"~것 같아요 softens almost any statement."}'::jsonb, 4),
  ('lesson-conversation-opinions-expression-5', 'lesson-conversation-opinions', 'expression', '네, 맞아요.', 'Yes, that''s right.', 'ne, majayo.', null, null, 5),
  ('lesson-conversation-opinions-expression-6', 'lesson-conversation-opinions', 'expression', '글쎄요, 조금 다르게 생각해요.', 'Hmm, I see it a little differently.', 'geulsseyo, jogeum dareuge saenggakhaeyo.', null, null, 6),
  ('lesson-conversation-opinions-listening-7', 'lesson-conversation-opinions', 'listening', '어떻게 생각하세요?', 'What do you think?', 'eotteoke saenggakhaseyo?', null, null, 7),
  ('lesson-conversation-opinions-speaking-8', 'lesson-conversation-opinions', 'speaking', '제 생각에는 괜찮은 것 같아요.', 'I think it seems fine.', 'je saenggageneun gwaenchaneun geot gatayo.', null, null, 8),
  ('lesson-conversation-opinions-summary-9', 'lesson-conversation-opinions', 'summary', null, null, null, null, '{"points":["~것 같아요 turns a claim into an impression.","글쎄요 buys you time and softens disagreement.","Direct contradiction is rare — lead with agreement, then adjust."]}'::jsonb, 9),
  ('lesson-conversation-feelings-introduction-0', 'lesson-conversation-feelings', 'introduction', null, 'Four adjectives cover most of what you need to say about your day.', null, null, '{"heading":"Talking About Feelings"}'::jsonb, 0),
  ('lesson-conversation-feelings-vocabulary-1', 'lesson-conversation-feelings', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-pigonhaeyo"}'::jsonb, 1),
  ('lesson-conversation-feelings-vocabulary-2', 'lesson-conversation-feelings', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-sinnayo"}'::jsonb, 2),
  ('lesson-conversation-feelings-vocabulary-3', 'lesson-conversation-feelings', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-seuteureseu"}'::jsonb, 3),
  ('lesson-conversation-feelings-vocabulary-4', 'lesson-conversation-feelings', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-seopseophaeyo"}'::jsonb, 4),
  ('lesson-conversation-feelings-expression-5', 'lesson-conversation-feelings', 'expression', '오늘 너무 피곤해요.', 'I''m so tired today.', 'oneul neomu pigonhaeyo.', null, null, 5),
  ('lesson-conversation-feelings-expression-6', 'lesson-conversation-feelings', 'expression', '요즘 스트레스 많이 받아요.', 'I''ve been really stressed lately.', 'yojeum seuteureseu mani badayo.', null, '{"note":"스트레스 pairs with 받다 — you \"receive\" stress."}'::jsonb, 6),
  ('lesson-conversation-feelings-expression-7', 'lesson-conversation-feelings', 'expression', '내일 여행 가서 신나요.', 'I''m excited to travel tomorrow.', 'naeil yeohaeng gaseo sinnayo.', null, null, 7),
  ('lesson-conversation-feelings-listening-8', 'lesson-conversation-feelings', 'listening', '괜찮아요? 무슨 일 있어요?', 'Are you okay? Is something wrong?', 'gwaenchanayo? museun il isseoyo?', null, null, 8),
  ('lesson-conversation-feelings-speaking-9', 'lesson-conversation-feelings', 'speaking', '조금 피곤하지만 괜찮아요.', 'I''m a bit tired but I''m fine.', 'jogeum pigonhajiman gwaenchanayo.', null, null, 9),
  ('lesson-conversation-feelings-summary-10', 'lesson-conversation-feelings', 'summary', null, null, null, null, '{"points":["너무 = \"so / too much\".","스트레스 받다 is the fixed pairing.","~지만 joins two clauses as \"but\"."]}'::jsonb, 10),
  ('lesson-conversation-plans-introduction-0', 'lesson-conversation-plans', 'introduction', null, 'Koreans make plans fast and confirm the day before. These lines do both.', null, null, '{"heading":"Making Plans"}'::jsonb, 0),
  ('lesson-conversation-plans-vocabulary-1', 'lesson-conversation-plans', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-yaksok"}'::jsonb, 1),
  ('lesson-conversation-plans-vocabulary-2', 'lesson-conversation-plans', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-eonje"}'::jsonb, 2),
  ('lesson-conversation-plans-vocabulary-3', 'lesson-conversation-plans', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-daeum-e"}'::jsonb, 3),
  ('lesson-conversation-plans-expression-4', 'lesson-conversation-plans', 'expression', '언제 시간 괜찮아요?', 'When are you free?', 'eonje sigan gwaenchanayo?', null, null, 4),
  ('lesson-conversation-plans-expression-5', 'lesson-conversation-plans', 'expression', '토요일 어때요?', 'How about Saturday?', 'toyoil eottaeyo?', null, null, 5),
  ('lesson-conversation-plans-expression-6', 'lesson-conversation-plans', 'expression', '그럼 그때 봬요.', 'See you then.', 'geureom geuttae bwaeyo.', null, null, 6),
  ('lesson-conversation-plans-listening-7', 'lesson-conversation-plans', 'listening', '이번 주말에 뭐 해요?', 'What are you doing this weekend?', 'ibeon jumare mwo haeyo?', null, null, 7),
  ('lesson-conversation-plans-speaking-8', 'lesson-conversation-plans', 'speaking', '토요일 어때요? 저는 괜찮아요.', 'How about Saturday? I am free.', 'toyoil eottaeyo? jeoneun gwaenchanayo.', null, null, 8),
  ('lesson-conversation-plans-summary-9', 'lesson-conversation-plans', 'summary', null, null, null, null, '{"points":["~ 어때요? proposes anything.","약속 means a plan with a person, not a promise.","봬요 is the polite \"see you\"."]}'::jsonb, 9),
  ('lesson-conversation-declining-introduction-0', 'lesson-conversation-declining', 'introduction', null, 'A flat 아니요 to an invitation feels cold. Korean declines with a reason and a future opening.', null, null, '{"heading":"Saying No Politely"}'::jsonb, 0),
  ('lesson-conversation-declining-vocabulary-1', 'lesson-conversation-declining', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-mianhajiman"}'::jsonb, 1),
  ('lesson-conversation-declining-vocabulary-2', 'lesson-conversation-declining', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-daeum-e"}'::jsonb, 2),
  ('lesson-conversation-declining-vocabulary-3', 'lesson-conversation-declining', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-yaksok"}'::jsonb, 3),
  ('lesson-conversation-declining-expression-4', 'lesson-conversation-declining', 'expression', '미안하지만 오늘은 어려울 것 같아요.', 'Sorry, today looks difficult for me.', 'mianhajiman oneureun eoryeoul geot gatayo.', null, null, 4),
  ('lesson-conversation-declining-expression-5', 'lesson-conversation-declining', 'expression', '다음에 꼭 같이 가요!', 'Let''s definitely go together next time!', 'daeume kkok gachi gayo!', null, null, 5),
  ('lesson-conversation-declining-expression-6', 'lesson-conversation-declining', 'expression', '이미 약속이 있어서요.', 'It is because I already have plans.', 'imi yaksogi isseoseoyo.', null, null, 6),
  ('lesson-conversation-declining-listening-7', 'lesson-conversation-declining', 'listening', '아쉽네요. 그럼 다음에요!', 'That''s a shame. Next time then!', 'aswimneyo. geureom daeumeyo!', null, null, 7),
  ('lesson-conversation-declining-speaking-8', 'lesson-conversation-declining', 'speaking', '미안하지만 다음에 갈게요.', 'Sorry, I''ll go next time.', 'mianhajiman daeume galgeyo.', null, null, 8),
  ('lesson-conversation-declining-summary-9', 'lesson-conversation-declining', 'summary', null, null, null, null, '{"points":["Always pair a decline with 다음에.","~아서요 gives a reason and softens the sentence end.","Ending on an invitation keeps the relationship warm."]}'::jsonb, 9),
  ('lesson-living-pharmacy-introduction-0', 'lesson-living-pharmacy', 'introduction', null, 'Korean pharmacists hand out medicine for minor issues without a prescription. Describe the symptom and they do the rest.', null, null, '{"heading":"At the Pharmacy"}'::jsonb, 0),
  ('lesson-living-pharmacy-vocabulary-1', 'lesson-living-pharmacy', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-yakguk"}'::jsonb, 1),
  ('lesson-living-pharmacy-vocabulary-2', 'lesson-living-pharmacy', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-yak"}'::jsonb, 2),
  ('lesson-living-pharmacy-vocabulary-3', 'lesson-living-pharmacy', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-apayo"}'::jsonb, 3),
  ('lesson-living-pharmacy-vocabulary-4', 'lesson-living-pharmacy', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-gamgi"}'::jsonb, 4),
  ('lesson-living-pharmacy-expression-5', 'lesson-living-pharmacy', 'expression', '감기약 주세요.', 'Cold medicine, please.', 'gamgiyak juseyo.', null, null, 5),
  ('lesson-living-pharmacy-expression-6', 'lesson-living-pharmacy', 'expression', '머리가 아파요.', 'My head hurts.', 'meoriga apayo.', null, '{"note":"Body part + 가/이 아파요 works for anything."}'::jsonb, 6),
  ('lesson-living-pharmacy-expression-7', 'lesson-living-pharmacy', 'expression', '하루에 몇 번 먹어요?', 'How many times a day do I take it?', 'harue myeot beon meogeoyo?', null, null, 7),
  ('lesson-living-pharmacy-listening-8', 'lesson-living-pharmacy', 'listening', '식후 삼십 분에 드세요.', 'Take it 30 minutes after meals.', 'sikhu samsip bune deuseyo.', null, null, 8),
  ('lesson-living-pharmacy-speaking-9', 'lesson-living-pharmacy', 'speaking', '목이 아파요. 약 주세요.', 'My throat hurts. Medicine, please.', 'mogi apayo. yak juseyo.', null, null, 9),
  ('lesson-living-pharmacy-summary-10', 'lesson-living-pharmacy', 'summary', null, null, null, null, '{"points":["~가 아파요 describes any pain.","약국 handles minor illness without a doctor.","식후 = after meals, 식전 = before meals."]}'::jsonb, 10),
  ('lesson-living-emergency-introduction-0', 'lesson-living-emergency', 'introduction', null, 'Short, loud and unambiguous. These are the sentences to memorise before you need them.', null, null, '{"heading":"Getting Help Fast"}'::jsonb, 0),
  ('lesson-living-emergency-vocabulary-1', 'lesson-living-emergency', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-dowajuseyo"}'::jsonb, 1),
  ('lesson-living-emergency-vocabulary-2', 'lesson-living-emergency', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-byeongwon"}'::jsonb, 2),
  ('lesson-living-emergency-vocabulary-3', 'lesson-living-emergency', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-apayo"}'::jsonb, 3),
  ('lesson-living-emergency-expression-4', 'lesson-living-emergency', 'expression', '도와주세요!', 'Please help me!', 'dowajuseyo!', null, null, 4),
  ('lesson-living-emergency-expression-5', 'lesson-living-emergency', 'expression', '119 불러 주세요.', 'Please call 119.', 'ilillgu bulleo juseyo.', null, '{"note":"119 is fire and ambulance; 112 is police."}'::jsonb, 5),
  ('lesson-living-emergency-expression-6', 'lesson-living-emergency', 'expression', '병원에 가야 해요.', 'I need to go to the hospital.', 'byeongwone gaya haeyo.', null, null, 6),
  ('lesson-living-emergency-listening-7', 'lesson-living-emergency', 'listening', '어디가 아프세요?', 'Where does it hurt?', 'eodiga apeuseyo?', null, null, 7),
  ('lesson-living-emergency-speaking-8', 'lesson-living-emergency', 'speaking', '도와주세요! 119 불러 주세요.', 'Help! Please call 119.', 'dowajuseyo! ilillgu bulleo juseyo.', null, null, 8),
  ('lesson-living-emergency-summary-9', 'lesson-living-emergency', 'summary', null, null, null, null, '{"points":["119 = ambulance and fire.","112 = police.","~아/어야 해요 means \"I have to\"."]}'::jsonb, 9),
  ('lesson-living-apartment-introduction-0', 'lesson-living-apartment', 'introduction', null, 'Most issues go through the 관리실 (management office) rather than the landlord directly.', null, null, '{"heading":"Apartment Problems"}'::jsonb, 0),
  ('lesson-living-apartment-vocabulary-1', 'lesson-living-apartment', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-jibju-in"}'::jsonb, 1),
  ('lesson-living-apartment-vocabulary-2', 'lesson-living-apartment', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-gowajang"}'::jsonb, 2),
  ('lesson-living-apartment-vocabulary-3', 'lesson-living-apartment', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-ttatteutan-mul"}'::jsonb, 3),
  ('lesson-living-apartment-vocabulary-4', 'lesson-living-apartment', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-gwanribi"}'::jsonb, 4),
  ('lesson-living-apartment-expression-5', 'lesson-living-apartment', 'expression', '뜨거운 물이 안 나와요.', 'There is no hot water.', 'tteugeoun muri an nawayo.', null, null, 5),
  ('lesson-living-apartment-expression-6', 'lesson-living-apartment', 'expression', '보일러가 고장났어요.', 'The boiler is broken.', 'boilleoga gojangnasseoyo.', null, null, 6),
  ('lesson-living-apartment-expression-7', 'lesson-living-apartment', 'expression', '언제 고쳐 주실 수 있어요?', 'When can you fix it?', 'eonje gochyeo jusil su isseoyo?', null, null, 7),
  ('lesson-living-apartment-listening-8', 'lesson-living-apartment', 'listening', '오늘 오후에 사람 보낼게요.', 'I''ll send someone this afternoon.', 'oneul ohue saram bonaelgeyo.', null, null, 8),
  ('lesson-living-apartment-speaking-9', 'lesson-living-apartment', 'speaking', '뜨거운 물이 안 나와요. 확인 부탁드려요.', 'There is no hot water. Please check it.', 'tteugeoun muri an nawayo. hwagin butakdeuryeoyo.', null, null, 9),
  ('lesson-living-apartment-summary-10', 'lesson-living-apartment', 'summary', null, null, null, null, '{"points":["안 + verb makes it negative.","고장났어요 covers any broken appliance.","관리비 is the monthly building fee, separate from rent."]}'::jsonb, 10),
  ('lesson-travel-hotel-introduction-0', 'lesson-travel-hotel', 'introduction', null, 'Four lines cover arrival, luggage, and getting an extra hour in the morning.', null, null, '{"heading":"Checking In"}'::jsonb, 0),
  ('lesson-travel-hotel-vocabulary-1', 'lesson-travel-hotel', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-yeyak"}'::jsonb, 1),
  ('lesson-travel-hotel-vocabulary-2', 'lesson-travel-hotel', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-chekeuin"}'::jsonb, 2),
  ('lesson-travel-hotel-vocabulary-3', 'lesson-travel-hotel', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-jim"}'::jsonb, 3),
  ('lesson-travel-hotel-expression-4', 'lesson-travel-hotel', 'expression', '체크인 하려고 하는데요.', 'I''d like to check in.', 'chekeuin haryeogo haneundeyo.', null, null, 4),
  ('lesson-travel-hotel-expression-5', 'lesson-travel-hotel', 'expression', '예약했어요. 이름은 알렉스입니다.', 'I have a reservation under Alex.', 'yeyakhaesseoyo. ireumeun alekseuimnida.', null, null, 5),
  ('lesson-travel-hotel-expression-6', 'lesson-travel-hotel', 'expression', '짐 좀 맡길 수 있어요?', 'Could I leave my luggage?', 'jim jom matgil su isseoyo?', null, null, 6),
  ('lesson-travel-hotel-listening-7', 'lesson-travel-hotel', 'listening', '체크아웃은 열한 시입니다.', 'Checkout is at 11.', 'chekeuauseun yeolhan siimnida.', null, null, 7),
  ('lesson-travel-hotel-speaking-8', 'lesson-travel-hotel', 'speaking', '체크인 하려고 하는데요. 예약했어요.', 'I''d like to check in. I have a reservation.', 'chekeuin haryeogo haneundeyo. yeyakhaesseoyo.', null, null, 8),
  ('lesson-travel-hotel-summary-9', 'lesson-travel-hotel', 'summary', null, null, null, null, '{"points":["~하려고 하는데요 politely states your intention.","~ㄹ 수 있어요? asks if something is possible.","Give your name in Roman letters — staff will find it."]}'::jsonb, 9),
  ('lesson-travel-sightseeing-introduction-0', 'lesson-travel-sightseeing', 'introduction', null, 'Buying entry and asking a stranger for a photo — the two things every traveller does daily.', null, null, '{"heading":"Tickets & Photos"}'::jsonb, 0),
  ('lesson-travel-sightseeing-vocabulary-1', 'lesson-travel-sightseeing', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-ipjangnyo"}'::jsonb, 1),
  ('lesson-travel-sightseeing-vocabulary-2', 'lesson-travel-sightseeing', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-sajin"}'::jsonb, 2),
  ('lesson-travel-sightseeing-vocabulary-3', 'lesson-travel-sightseeing', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-eolmayeyo"}'::jsonb, 3),
  ('lesson-travel-sightseeing-expression-4', 'lesson-travel-sightseeing', 'expression', '어른 두 장 주세요.', 'Two adult tickets, please.', 'eoreun du jang juseyo.', null, null, 4),
  ('lesson-travel-sightseeing-expression-5', 'lesson-travel-sightseeing', 'expression', '사진 좀 찍어 주실 수 있어요?', 'Could you take a photo for me?', 'sajin jom jjigeo jusil su isseoyo?', null, null, 5),
  ('lesson-travel-sightseeing-expression-6', 'lesson-travel-sightseeing', 'expression', '여기서 사진 찍어도 돼요?', 'May I take photos here?', 'yeogiseo sajin jjigeodo dwaeyo?', null, null, 6),
  ('lesson-travel-sightseeing-listening-7', 'lesson-travel-sightseeing', 'listening', '입장은 다섯 시까지입니다.', 'Entry is until 5pm.', 'ipjangeun daseot sikkajiimnida.', null, null, 7),
  ('lesson-travel-sightseeing-speaking-8', 'lesson-travel-sightseeing', 'speaking', '사진 좀 찍어 주실 수 있어요?', 'Could you take a photo for me?', 'sajin jom jjigeo jusil su isseoyo?', null, null, 8),
  ('lesson-travel-sightseeing-summary-9', 'lesson-travel-sightseeing', 'summary', null, null, null, null, '{"points":["장 counts flat things like tickets.","~주실 수 있어요? is a very polite request.","~해도 돼요? asks permission."]}'::jsonb, 9),
  ('lesson-work-email-introduction-0', 'lesson-work-email', 'introduction', null, 'Korean work writing follows a fixed skeleton: greeting, context, request, closing. Fill in the blanks and you sound native.', null, null, '{"heading":"Writing a Work Message"}'::jsonb, 0),
  ('lesson-work-email-vocabulary-1', 'lesson-work-email', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-butakdeurimnida"}'::jsonb, 1),
  ('lesson-work-email-vocabulary-2', 'lesson-work-email', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-hwagin"}'::jsonb, 2),
  ('lesson-work-email-vocabulary-3', 'lesson-work-email', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-jeonhandeurimnida"}'::jsonb, 3),
  ('lesson-work-email-vocabulary-4', 'lesson-work-email', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-ilcheong"}'::jsonb, 4),
  ('lesson-work-email-expression-5', 'lesson-work-email', 'expression', '안녕하세요, 마케팅팀 알렉스입니다.', 'Hello, this is Alex from the marketing team.', 'annyeonghaseyo, maketingtim alekseuimnida.', null, null, 5),
  ('lesson-work-email-expression-6', 'lesson-work-email', 'expression', '자료 전달드립니다.', 'I am forwarding the materials.', 'jaryo jeondaldeurimnida.', null, null, 6),
  ('lesson-work-email-expression-7', 'lesson-work-email', 'expression', '확인 부탁드립니다.', 'Please kindly confirm.', 'hwagin butakdeurimnida.', null, '{"note":"The standard closing request in Korean work mail."}'::jsonb, 7),
  ('lesson-work-email-listening-8', 'lesson-work-email', 'listening', '일정 조정 가능할까요?', 'Would adjusting the schedule be possible?', 'iljeong jojeong ganeunghalkkayo?', null, null, 8),
  ('lesson-work-email-speaking-9', 'lesson-work-email', 'speaking', '확인 부탁드립니다. 감사합니다.', 'Please kindly confirm. Thank you.', 'hwagin butakdeurimnida. gamsahamnida.', null, null, 9),
  ('lesson-work-email-summary-10', 'lesson-work-email', 'summary', null, null, null, null, '{"points":["Open by naming your team and yourself.","~드립니다 is the humble form that makes writing polite.","Close with 부탁드립니다 or 감사합니다."]}'::jsonb, 10)
insert into public.quizzes (id, lesson_id, question_type, question, prompt, correct_answer, options, metadata)
values
  ('q-hello-1', 'lesson-greetings-hello', 'multiple_choice_ko_en', 'What does 안녕하세요 mean?', '안녕하세요', 'Hello', ARRAY['Hello', 'Thank you', 'Goodbye', 'Sorry']::text[], null),
  ('q-hello-2', 'lesson-greetings-hello', 'multiple_choice_en_ko', 'How do you say goodbye to someone who is leaving?', null, '안녕히 가세요', ARRAY['안녕히 가세요', '안녕히 계세요', '감사합니다', '반가워요']::text[], null),
  ('q-hello-3', 'lesson-greetings-hello', 'true_false', '안녕하세요 can be used in the morning and the evening.', null, 'True', ARRAY['True', 'False']::text[], null),
  ('q-hello-4', 'lesson-greetings-hello', 'sentence_ordering', 'Put the sentence in the right order.', 'Nice to meet you.', '만나서 반가워요', ARRAY['만나서', '반가워요']::text[], null),
  ('q-yesno-1', 'lesson-greetings-yesno', 'multiple_choice_ko_en', 'What does 아니요 mean?', '아니요', 'No', ARRAY['No', 'Yes', 'Maybe', 'Please']::text[], null),
  ('q-yesno-2', 'lesson-greetings-yesno', 'fill_in_the_blank', 'Complete: ___, 괜찮아요. ("No, I''m fine.")', '___, 괜찮아요.', '아니요', ARRAY['아니요', '네', '주세요', '감사']::text[], null),
  ('q-thanks-1', 'lesson-greetings-thanks', 'multiple_choice_en_ko', 'How do you say "thank you" formally?', null, '감사합니다', ARRAY['감사합니다', '죄송합니다', '천만에요', '괜찮아요']::text[], null),
  ('q-thanks-2', 'lesson-greetings-thanks', 'multiple_choice_ko_en', 'What does 죄송합니다 mean?', '죄송합니다', 'I am sorry', ARRAY['I am sorry', 'Thank you', 'You are welcome', 'Excuse me']::text[], null),
